<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3'; import { Button } from '@/components/ui/button';
type Permission = { id: string; name: string; label: string }; type Group = { group: string; permissions: Permission[] }; type Role = { id: string; name: string; label: string; description: string; permissions: string[] };
const props = defineProps<{ role: Role; permissionGroups: Group[] }>(); const form = useForm({ permissions: [...props.role.permissions] }); const submit = () => form.put(`/roles/${props.role.id}/permissions`, { preserveScroll: true });
</script>
<template><Head :title="`Permisos de ${role.label}`" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">{{ role.label }}</h1><p class="text-sm text-muted-foreground">{{ role.description }}</p></header><form class="space-y-4" @submit.prevent="submit"><section v-for="group in permissionGroups" :key="group.group" class="rounded-xl border bg-card p-5"><h2 class="mb-3 font-semibold">{{ group.group }}</h2><div class="grid gap-2 md:grid-cols-2"><label v-for="permission in group.permissions" :key="permission.id" class="flex gap-2 rounded-md border p-3 text-sm"><input v-model="form.permissions" type="checkbox" :value="permission.id" class="size-4 accent-amber-700" /><span><span class="block font-medium">{{ permission.label }}</span><code class="text-xs text-muted-foreground">{{ permission.name }}</code></span></label></div></section><div class="sticky bottom-4 flex justify-end"><Button type="submit" :disabled="form.processing">Guardar permisos</Button></div></form></main></template>
